"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4809],{94809:e=>{e.exports=JSON.parse('{"slug":"uyazvimost-php2shell-sayty-bankov-oktyabr-2026","locale":"zh","title":"PHP漏洞后，安全部门要求银行与政府关闭尚未更新的网站","description":"PHP发现两项严重漏洞，安全部门要求银行与政府更新或暂时关闭。解释为何一个错误影响整个互联网。","blocks":[{"id":"b001","kind":"paragraph","text":"PHP开发者十月21日发布两项称为PHP2Shell的漏洞补丁，危险评分均为9.2/10。攻击者无需密码，仅一次请求即可在服务器执行代码并访问数据。原定稍后披露的细节提前泄露。Amazon蜜罐十月17日就发现首次攻击，比补丁早4天。Wiz认为漏洞已存在数十年，现代AI模型帮助其成为可用入侵手段。"},{"id":"b002","kind":"paragraph","text":"十月22日，联邦安全局下属全国计算机事件协调中心通过国家攻击检测系统发信，收件者是关键基础设施：政府、金融、能源、交通和医疗机构。要求更新PHP并查杀服务器。若不能迅速更新，应限制脆弱服务器外部访问或关闭。"},{"id":"b003","kind":"paragraph","text":"设想一座城市大多数楼门使用同家锁，突然发现同一把钥匙可开全部，复制品已流传。大家需同时换锁，师傅未到前最好从内关门。经济学称系统风险：共同方案出故障，所有人同时受损。PHP免费方便，被互联网大量使用，也使一个错误变为公共问题。"},{"id":"b004","kind":"paragraph","text":"其他国家已关站。英国暂停32项政府服务，称更新期间的预防措施；比利时、荷兰、芬兰、法国和德国政府网站也曾不可用。网络安全公司报告数百万利用尝试。俄罗斯尚无大规模停站或入侵数据。"},{"id":"b005","kind":"paragraph","text":"用户可能暂时无法打开银行、政府网站或账户，这本身不代表被攻破，可能是更新时主动关闭。企业停站损失销售和客户满意度，入侵却更贵，包括泄露、罚款、资金被盗与恢复。因此协调中心选择短暂停机。"},{"id":"b006","kind":"paragraph","text":"更新耗时因机构而异。大型银行流程完善，可在数小时内补丁；小企业和使用已停止支持旧PHP的网站可能长期脆弱。企业检查日志后才知道成功入侵规模。近几日短暂故障多意味着安装补丁；更危险的是未更新却若无其事继续运行的服务器。"},{"id":"b007","kind":"heading","text":"PHP2Shell是什么漏洞？"},{"id":"b008","kind":"paragraph","text":"PHP语言两项错误CVE-2026-109618和CVE-2026-109619，评分9.2/10。无需密码的一次请求可执行服务器代码并访问数据，补丁于2026年十月21日发布。"},{"id":"b009","kind":"heading","text":"银行和政府网站会无法使用吗？"},{"id":"b010","kind":"paragraph","text":"可能在更新期间暂时如此。十月22日安全部门要求包括银行与政府的关键设施紧急更新PHP，来不及时限制访问或关闭。尚无俄罗斯大规模停站数据。"},{"id":"b011","kind":"heading","text":"一个错误为何影响这么多网站？"},{"id":"b012","kind":"paragraph","text":"PHP用于全球约70%网站和超过90%俄语网站。数百万站共享基础，基础漏洞同时打开风险，每个所有者都必须自行安装修复。"}],"sources":[{"label":"RBC：安全部门建议因PHP漏洞暂关网站","url":"https://www.kommersant.ru/doc/9045269"},{"label":"安全协调中心要求因PHP漏洞关闭未更新网站","url":"https://frankmedia.ru/311764"},{"label":"PHP2Shell严重漏洞已修补，请更新","url":"https://www.helpnetsecurity.com/2026/10/21/php2shell-php-vulnerabilities-patched-cve-2026-109618-cve-2026-109619/"},{"label":"PHP2Shell：泄露的严重漏洞面临大规模利用","url":"https://www.securityweek.com/php2shell-mass-exploitation-looms-for-leaked-critical-php-flaws/"},{"label":"全球网站遭数百万次PHP漏洞利用尝试","url":"https://www.theguardian.com/technology/2026/oct/22/websites-across-world-hit-by-millions-of-attempts-to-exploit-php-code-flaw"},{"label":"PHP2Shell使数十英国政府服务停用","url":"https://www.theregister.com/security/2026/10/22/php2shell-puts-dozens-of-uk-government-services-out-of-service/5304840"},{"label":"AI发现的两项网页安全漏洞引发全球警报","url":"https://www.forbes.ru/tekhnologii/570823-vyavlennye-s-pomos-u-ii-dve-uazvimosti-v-veb-bezopasnosti-vyzvali-trevogu-v-mire"}],"sourceBodySha256":"e3fb2a77720fe8860c329873f043e4f7761ab7ab4c70849c9068a88ee60dd68e"}')}}]);